export const professionCategories = [...new Set(professions.map(p => p.category))];

export function getProfessionsByCategory(): Record<string, ProfessionData[]> {
  return professions.reduce((acc, p) => {
    if (!acc[p.category]) acc[p.category] = [];
    acc[p.category].push(p);
    return acc;
  }, {} as Record<string, ProfessionData[]>);
}
